def pmx_crossover(parent1, parent2):
    """
    Partially Mapped Crossover (PMX) for genetic algorithms.
    Applies PMX separately to each car's route.

    Parameters:
        - parent1 (list of lists): First parent, where each sublist represents a car's route.
        - parent2 (list of lists): Second parent, structured similarly.

    Returns:
        - list of lists: Offspring with routes for multiple cars.
    """
    def apply_pmx(p1, p2):
        """ Apply PMX on a single route (sublist) """
        size = len(p1)
        child = [-1] * size  

        start, end = sorted(np.random.choice(range(size), 2, replace=False))

        child[start:end + 1] = p1[start:end + 1]

        mapping = {p1[i]: p2[i] for i in range(start, end + 1)}

        for i in range(size):
            if child[i] == -1:  
                candidate = p2[i]
                while candidate in mapping:  
                    candidate = mapping[candidate]
                child[i] = candidate

        return child

    # Apply PMX to each car's route separately
    return [apply_pmx(r1, r2) for r1, r2 in zip(parent1, parent2)]





