#UPDATED FUNCTION
def adaptive_mutate(route, mutation_rate, diversity_factor=0.2):
    """
    Applies adaptive mutation based on population diversity.

    Parameters:
        - route (list): The route to mutate.
        - mutation_rate (float): Base mutation rate.
        - diversity_factor (float): Scaling factor to adjust mutation rate dynamically.

    Returns:
        - list: Mutated route.
    """
    adaptive_rate = mutation_rate + np.random.uniform(-diversity_factor, diversity_factor)
    
    if np.random.rand() < max(0.01, adaptive_rate):  # Ensure mutation rate doesn't drop too low
        i, j = np.random.choice(len(route), 2, replace=False)
        route[i], route[j] = route[j], route[i]
    
    return route




    
