#UPDATED FUNCTION
def generate_unique_population_multiple_cars(population_size, num_nodes, num_cars):
    """
    Generate a unique population of individuals for a genetic algorithm.
    Each individual represents routes for multiple cars.

    Parameters:
        - population_size (int): Number of individuals in the population.
        - num_nodes (int): Number of delivery locations (excluding the depot).
        - num_cars (int): Number of cars available for deliveries.

    Returns:
        - list of lists: A list of unique individuals, where each individual 
          consists of multiple sub-routes (one per car).
    """
    population = set()

    while len(population) < population_size:
        # Generate a shuffled list of delivery locations
        locations = list(np.random.permutation(np.arange(1, num_nodes)))

        # Split locations into 'num_cars' separate routes
        split_routes = np.array_split(locations, num_cars)
        
        # Convert back to lists and add depot (node 0) at the beginning of each route
        individual = [[0] + list(route) for route in split_routes]
        
        population.add(tuple(tuple(sub_route) for sub_route in individual))  # Ensure uniqueness

    return [list(map(list, ind)) for ind in population]  # Convert back to list format

